head.script:
scwin.onpageload = function() {		
			gp_generator.insertChild()
			gp_generator.insertChild()
			gp_generator.insertChild()
};		
scwin.ge_searchbox_onchange = function() {
	localStorage.setItem("log", 'searchBox_onchange');			
    console.log("searchBox_onchange");
};

scwin.schBox_onchange = function() {
     console.log("schBox_onchange");
};


	scwin.checkVal = function() {
		return localStorage.getItem('log') == 'searchBox_onchange';
	}	
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gp_generator_0_ge_searchbox___input').click()");
		WebSquare.wUnit.addCommand("pause", "400");			
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gp_generator_0_ge_searchbox___input').focus()");
		WebSquare.wUnit.addCommand("pause", "400");				
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gp_generator_0_ge_searchbox___input').value = '1'");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gp_generator_1_ge_searchbox___input').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gp_generator_1_ge_searchbox___input').focus()");
		WebSquare.wUnit.addCommand("pause", "400");			

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
	localStorage.removeItem("log");
